-- Marca neutra (docs/marca-neutra, T05): dados da empresa-modelo sem marca de cliente e pasta de
-- imagens da apresentação renomeada (/imagens/apresentacao/). Só acrescenta/neutraliza; não apaga.

-- 1) Caminho das imagens estáticas (todas as empresas): a pasta do sistema mudou de nome.
update crm.apresentacao_conteudo
   set conteudo = replace(conteudo::text, '/imagens/apresentacao-garbo/', '/imagens/apresentacao/')::jsonb,
       pontua = replace(pontua::text, '/imagens/apresentacao-garbo/', '/imagens/apresentacao/')::jsonb
 where conteudo::text like '%/imagens/apresentacao-garbo/%' or pontua::text like '%/imagens/apresentacao-garbo/%';
update crm.orcamento_slide_blocos
   set config = replace(config::text, '/imagens/apresentacao-garbo/', '/imagens/apresentacao/')::jsonb
 where config::text like '%/imagens/apresentacao-garbo/%';

-- 2) Empresas-modelo: apresentação e Pontua no padrão neutro ({empresa} vira o nome de quem recebe).
--    JSON gerado de CONTEUDO_NEUTRO / PONTUA_NEUTRO por scripts/marca-neutra/gerar-conteudo-neutro.mjs.
update crm.apresentacao_conteudo a
   set conteudo = $json${"marca":{"sobrescrito":"{empresa}","titulo":"{empresa}","subtitulo":"","slogan":"Precisão na execução para arquitetos que levam o próprio nome a sério."},"imagens":{"hero":"/imagens/apresentacao/projetos/suite-painel-ripado.png","origem":"/imagens/apresentacao/projetos/painel-madeira-continuidade.png","proposta":"/imagens/apresentacao/proposta-banco.jpg","fechamento":"/imagens/apresentacao/projetos/painel-madeira-continuidade.png"},"secoes":[{"id":"origem","eyebrow":"A ORIGEM","title":"Por que a {empresa} existe","paragraphs":["Nascemos dentro da oficina, onde madeira não mente: ela revela o capricho de quem a trabalhou e o respeito pelo projeto.","Vimos o mercado prometer muito e entregar pouco, tratando o projeto do arquiteto como sugestão. Decidimos fazer diferente."],"highlight":"Não como mais uma empresa. Como uma resposta."},{"id":"proposta","eyebrow":"A PROPOSTA","title":"O que a {empresa} resolve","paragraphs":["Um princípio único: o projeto do arquiteto é sagrado.","Cada medida, cada detalhe, cada ferragem executados com precisão, com materiais de primeira e comunicação que você acompanha do começo ao fim."],"highlight":"Você é o autor. Nós somos o instrumento."},{"id":"prova-social","eyebrow":"PROVA SOCIAL","title":"O que nossos parceiros dizem","paragraphs":["Arquitetos que trabalham conosco uma vez raramente buscam outro fornecedor: não querem mais correr o risco de trabalhar sem uma parceria assim."],"highlight":"A reputação do seu escritório é construída em cada entrega. A nossa também."}],"fechamento":{"eyebrow":"FECHAMENTO","title":"Uma parceria, não um orçamento","paragraphs":["Crescemos na qualidade, não no volume.","Trabalhamos com um número limitado de projetos por vez, para que cada um receba a atenção que merece."],"closing":"Se você chegou até aqui, já entendeu: o que oferecemos é uma parceria.","ctaLabel":"Iniciar parceria","ctaHint":"A {empresa} irá entrar em contato com você."},"projetos":{"eyebrow":"PROJETOS & OBRAS","title":"A {empresa} em cada detalhe","subtitle":"Ambientes executados com precisão — madeira, luz e acabamento no formato da obra real.","hint":"Deslize o carrossel","items":[{"id":"suite-painel-ripado","type":"image","src":"/imagens/apresentacao/projetos/suite-painel-ripado.png","title":"Suíte com painel e espelho","caption":"TV embutida, espelho orgânico retroiluminado e console flutuante em madeira."},{"id":"cozinha-cristaleira","type":"image","src":"/imagens/apresentacao/projetos/cozinha-cristaleira.png","title":"Cristaleira iluminada","caption":"Vitrine floor-to-ceiling com LED integrado e organização impecável."},{"id":"sala-cozinha-integrada","type":"image","src":"/imagens/apresentacao/projetos/sala-cozinha-integrada.png","title":"Sala e cozinha integradas","caption":"Ambiente aberto com sofá, marcenaria sob medida e ilha iluminada."},{"id":"suite-nichos-led","type":"image","src":"/imagens/apresentacao/projetos/cubo-suite-trofeus.png","title":"Suíte com nichos iluminados","caption":"Ripado, LED em V e prateleiras que valorizam cada detalhe."},{"id":"painel-madeira-continuidade","type":"image","src":"/imagens/apresentacao/projetos/painel-madeira-continuidade.png","title":"Painel em continuidade","caption":"Madeira do piso à parede — volume único, luz quente e acabamento preciso."}]},"cubo":[{"id":"cubo-cristaleira","src":"/imagens/apresentacao/projetos/cubo-cristaleira.png","title":"Cristaleira iluminada","caption":"Vitrine floor-to-ceiling com LED e organização impecável."},{"id":"cubo-sala-integrada","src":"/imagens/apresentacao/projetos/cubo-sala-integrada.png","title":"Sala e cozinha integradas","caption":"Ambiente aberto com marcenaria sob medida e iluminação quente."},{"id":"cubo-painel-madeira","src":"/imagens/apresentacao/projetos/cubo-painel-madeira.png","title":"Painel em continuidade","caption":"Madeira do piso à parede — volume único e acabamento preciso."},{"id":"cubo-suite-trofeus","src":"/imagens/apresentacao/projetos/cubo-suite-trofeus.png","title":"Suíte com nichos iluminados","caption":"Ripado, LED em V e prateleiras que valorizam cada detalhe."},{"id":"cubo-suite-tv","src":"/imagens/apresentacao/projetos/cubo-suite-tv.png","title":"Suíte com painel e espelho","caption":"TV embutida, espelho orgânico retroiluminado e console flutuante."}],"instagram":{"eyebrow":"INSTAGRAM","title":"Entre no feed da oficina","subtitle":"Obras, detalhes e o dia a dia da {empresa}.","handle":"","profileUrl":"","embedUrl":"","profileCta":"Abrir Instagram","phoneDisplay":"","phoneTel":"","phoneWhatsApp":"","phoneLabel":"Falar agora"},"contato":{"aviso":"A {empresa} irá entrar em contato com você.","formTexto":"Cadastre-se para iniciar a parceria. A {empresa} irá entrar em contato com você —","formSucesso":"Recebemos seus dados. A {empresa} irá entrar em contato com você em breve.","formRodape":"Cadastro de prestador · vinculado à {empresa}","rodapeInstagram":"{empresa}"}}$json$::jsonb,
       pontua = $json${"eyebrow":"PROGRAMA DE PONTUAÇÃO","title":"Programa de pontuação para parceiros","subtitle":"Veja, na prática, como o arquiteto acompanha comissões, saldos e saques — com números de exemplo para facilitar o entendimento.","badge":"Demonstração com dados fictícios","parceiro":{"nome":"Ana Paula Mendes","escritorio":"Mendes Arquitetura","cidade":"Pouso Alegre · MG","percentual":10},"metricas":{"aGanar":8450,"paraSacar":12380,"retirado":24500,"aguardandoLiberacao":2100,"totalComissaoGanha":36880,"ganhoMesAtual":4200,"mediaMensalGanhos":6146.67},"ganhosPorMes":[{"key":"2025-10","label":"Out/25","valor":3800},{"key":"2025-11","label":"Nov/25","valor":5200},{"key":"2025-12","label":"Dez/25","valor":6100},{"key":"2026-01","label":"Jan/26","valor":4900},{"key":"2026-02","label":"Fev/26","valor":8680},{"key":"2026-03","label":"Mar/26","valor":4200}],"passos":[{"step":"01","title":"Indique e acompanhe","text":"Cada projeto indicado pelo parceiro entra no CRM da {empresa}. A comissão fica vinculada à venda."},{"step":"02","title":"Venda realizada","text":"Quando a obra é fechada, a comissão (ex.: 10%) é calculada automaticamente sobre o valor da venda."},{"step":"03","title":"Saldo e saque","text":"O arquiteto vê o que está a ganhar, o que já pode sacar e solicita o PIX direto pelo painel."}],"comissoes":[{"id":"c1","projeto":"Residência Serra Verde","cliente":"Família Oliveira","valorVenda":86000,"comissao":8600,"status":"pago","data":"12/02/2026"},{"id":"c2","projeto":"Apartamento Centro","cliente":"Carla Nogueira","valorVenda":42000,"comissao":4200,"status":"liberado","data":"03/03/2026"},{"id":"c3","projeto":"Closet + suíte master","cliente":"Roberto Lima","valorVenda":28500,"comissao":2850,"status":"em_andamento","data":"Em andamento"},{"id":"c4","projeto":"Cozinha integrada","cliente":"Studio Horizonte","valorVenda":21000,"comissao":2100,"status":"aguardando","data":"Aguardando liberação"}],"saques":[{"id":"s1","valor":8500,"status":"aprovado","data":"28/01/2026"},{"id":"s2","valor":6200,"status":"aprovado","data":"18/02/2026"},{"id":"s3","valor":4800,"status":"pendente","data":"08/03/2026"}]}$json$::jsonb,
       atualizado_em = now()
  from public."CRM-multi-empresas>empresas<" e
 where e.id = a.empresa_id and e.e_modelo;

-- 3) Contratos das empresas-modelo: dados da contratada viram variáveis da empresa (Perfil → Dados).
update crm.contratos_modelos c
   set conteudo = regexp_replace(
         regexp_replace(c.conteudo,
           'CONTRATADO: Garbo Movelaria[^\n]*',
           'CONTRATADO: {{empresa_razao_social}}, inscrita no CNPJ sob o nº {{empresa_cnpj}}, Telefone: {{empresa_telefone}}, neste ato representada por {{empresa_representante_nome}}, {{empresa_representante_qualificacao}}, inscrito no CPF sob o nº {{empresa_representante_cpf}}, com endereço profissional na {{empresa_endereco}}.'),
         '\(Chave CNPJ: 58\.838\.942/0001-23 - Garbo Movelaria\)',
         '(Chave CNPJ: {{empresa_cnpj}} - {{empresa_razao_social}})', 'g'),
       updated_at = now()
  from public."CRM-multi-empresas>empresas<" e
 where e.id = c.empresa_id and e.e_modelo and c.conteudo ~* 'garbo';

-- 4) Slide de garantia das empresas-modelo: texto sem nome de empresa.
update crm.orcamento_slide_blocos b
   set config = jsonb_set(b.config, '{texto}', to_jsonb(regexp_replace(b.config->>'texto',
         'A Garbo preza pela máxima qualidade, durabilidade e acabamento de seus móveis',
         'Prezamos pela máxima qualidade, durabilidade e acabamento dos nossos móveis')))
  from public."CRM-multi-empresas>empresas<" e
 where e.id = b.empresa_id and e.e_modelo and b.config->>'texto' ~* 'garbo';
